        </ToggleButtonGroup>
      </div>
      <ul className="mt-12 grid gap-5 lg:grid-cols-3">
        {plans.map((plan) => (
          <li
            key={plan.name}
            className={cn(
              "relative flex flex-col rounded-2xl bg-card p-5 shadow-[var(--shadow-card)] ring-1 ring-border/70 sm:p-6",
              plan.popular && "ring-2 ring-primary lg:-my-3 lg:py-9",
            )}
          >
            {plan.popular && (
              <Badge
                variant="accent"
                className="absolute -top-3 start-1/2 -translate-x-1/2 rtl:translate-x-1/2"
              >
                Most popular
              </Badge>
            )}
            <h2 className="text-lg font-semibold tracking-[-0.03em]">
              {plan.name}
            </h2>
            <p className="mt-1 text-sm leading-6 text-muted-foreground">
              {plan.description}
            </p>
            <p className="mt-5 flex items-baseline gap-1">
              <AnimatedNumber
                value={plan[cycle]}
                formatOptions={priceFormat}
                className="text-4xl font-semibold tracking-[-0.05em]"
              />
              <span className="text-sm text-muted-foreground">
                per seat each month
              </span>
            </p>
            <p className="mt-1 h-5 text-xs text-muted-foreground">
              {cycle === "yearly" && plan.yearly > 0
                ? `$${plan.yearly * 12} billed once a year`
                : ""}
            </p>
            <Button
              variant={plan.popular ? "default" : "outline"}
              className="mt-5 w-full"
            >
              {plan.action}
            </Button>
            <ul className="mt-6 grid gap-3 border-t border-border/70 pt-5 text-sm">
              {plan.features.map((feature) => (
                <li key={feature} className="flex items-center gap-3">
                  <CheckIcon
                    size={16}
                    weight="bold"
                    className="shrink-0 text-primary"
                    aria-hidden="true"
                  />
                  {feature}
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ul>
      <p className="mt-10 text-center text-sm text-muted-foreground">
        Prices are in US dollars. Taxes can apply.
      </p>
    </section>
  );
}
